            {mode === 'file'
              ? 'Uploading the fixture package and creating its durable receiptâ€¦'
              : role === 'admin'
                ? 'Validating the privileged administrator importâ€¦'
                : 'Staging the technical submission for validation and reviewâ€¦'}
          </p>
        ) : null}

        <div id={resultDescriptionId} ref={resultRegionRef}>
          {result.kind === 'acceptedBatch' ? (
            <div className="submission-result submission-result--success" role="status">
              <h2 tabIndex={-1} data-result-heading>
