 294:       setResult({ kind: 'idle' });
 295:     }
 296:   }
 297: 
 298:   async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
 299:     event.preventDefault();
 300: 
 301:     if (
 302:       result.kind === 'submitting' ||
 303:       result.kind === 'accepted' ||
 304:       result.kind === 'acceptedBatch'
 305:     ) {
 306:       return;
 307:     }
 308: 
 309:     if (mode === 'file' && !file) {
 310:       setResult({
 311:         kind: 'rejected',
 312:         message: 'Choose a JSON or CSV file before submitting.',
 313:         details: [],
 314:       });
 315:       return;
 316:     }
 317: 
 318:     setResult({ kind: 'submitting' });
 319: 
 320:     try {
 321:       if (mode === 'file' && file) {
 322:         if (!/\.(json|csv)$/i.test(file.name)) {
 323:           throw new SubmissionInputError('Choose a JSON or CSV fixture package.');
 324:         }
 325:         if (file.size > MAX_BATCH_BYTES) {
 326:           throw new BatchUploadInputError('The package is larger than the 50 MB upload limit.');
 327:         }
 328:         const fixture = fixtures.find((candidate) => candidate.fixtureId === fixtureId);
 329:         if (!fixture?.competitionId) {
 330:           throw new SubmissionInputError('Select an available fixture before uploading.');
 331:         }
 332:         validateSingleFixturePackage(file.name, await readFileText(file), fixture);
 333:         const response = await uploadBatch(client, fixture.competitionId, file, decisionKey);
 334: 
 335:         invalidateBatchCollections();
 336:         setResult({
 337:           kind: 'acceptedBatch',
 338:           receipt: response.data,
 339:           fixture,
 340:         });
 341:       } else {
 342:         const fixture = fixtures.find((candidate) => candidate.fixtureId === fixtureId);
 343:         if (!fixture?.competitionId) {
 344:           throw new SubmissionInputError('Select an available fixture before submitting.');
 345:         }
 346: 
 347:         if (role === 'admin') {
 348:           const accepted = await submitLegacyAdminEvents(client, fixtureId, eventJson);
 349:           setResult({
 350:             kind: 'accepted',
 351:             response: accepted.response,
 352:             correctionContext: { events: accepted.events, fixture },
 353:           });
 354:         } else {
 355:           const technicalFile = createTechnicalBatchFile(fixture, eventJson, decisionKey);
 356:           const response = await uploadBatch(
 357:             client,
 358:             fixture.competitionId,
 359:             technicalFile,
 360:             decisionKey,
 361:           );
 362: 
 363:           invalidateBatchCollections();
 364:           setResult({
 365:             kind: 'acceptedBatch',
 366:             receipt: response.data,
